// Cloudflare Worker entry: the site as built by OpenNext, plus a daily Cron Trigger (wrangler.jsonc, "triggers")
// that runs the maintenance link: trims old view logs and unpaid orders, and touches the database so a free
// Supabase project isn't paused. See src/app/api/health/route.ts.
// Imports .open-next/worker.js, generated by `opennextjs-cloudflare build`, so it is left out of tsconfig.
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: unknown, ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(handler.fetch(new Request("https://oliu.internal/api/health?db=1"), env, ctx));
  },
};

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
